/* Generated by scripts/split-content.mjs / merge-additions.mjs — do not edit by hand.
   The glossary and a sample of the question bank. The rest is served
   from the content function once entitlement is confirmed. */
window.DATA = {"cards":[{"id":"c000","term":"Pod","def":"The smallest deployable unit in Kubernetes. Contains one or more containers sharing network and storage. Ephemeral by design.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c001","term":"Deployment","def":"Declarative specification for Pods and ReplicaSets. Manages rolling updates, rollbacks, and scaling.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c002","term":"ReplicaSet","def":"Ensures a specified number of identical Pods are running. Created and managed by Deployments; rarely used directly.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c003","term":"Service (Kubernetes)","def":"Stable network endpoint for a set of Pods. Types: ClusterIP (internal), NodePort (external via node), LoadBalancer (cloud LB), ExternalName (DNS alias).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c004","term":"Ingress","def":"API object managing external HTTP/HTTPS access to Services. Provides host/path routing, TLS termination, and name-based virtual hosting.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c005","term":"ConfigMap / Secret","def":"ConfigMap stores non-sensitive configuration as key-value pairs. Secret stores sensitive data (base64-encoded, not encrypted by default).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c006","term":"Namespace","def":"Virtual cluster within a physical cluster. Provides scope for names and resource quotas. Default, kube-system, and kube-public are built-in.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c007","term":"PersistentVolume / PVC","def":"PV is a cluster storage resource. PVC is a user's request for storage. Dynamic provisioning creates PVs automatically from StorageClasses.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c008","term":"StatefulSet","def":"Like a Deployment but for stateful applications. Provides stable network identity, ordered deployment/scaling, and persistent storage per Pod.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c009","term":"DaemonSet","def":"Ensures a copy of a Pod runs on every (or selected) node. Used for log collectors, monitoring agents, and network plugins.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c010","term":"Job / CronJob","def":"Job runs a Pod to completion. CronJob schedules Jobs on a cron schedule. Both handle batch and periodic workloads.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c011","term":"kubectl","def":"Command-line tool for interacting with Kubernetes clusters. Applies manifests, inspects resources, streams logs, and executes into containers.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c012","term":"etcd","def":"Distributed key-value store used as Kubernetes' backing store for all cluster data. Consistency and backup are critical for cluster recovery.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c013","term":"Control Plane Components","def":"API server (front-end), etcd (state store), scheduler (assigns Pods to nodes), controller manager (maintains desired state).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c014","term":"kubelet","def":"Agent running on every node. Ensures containers described in PodSpecs are running and healthy. Reports node status to the API server.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c015","term":"kube-proxy","def":"Network proxy on each node implementing Service abstraction. Maintains iptables or IPVS rules for routing traffic to Pod endpoints.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c016","term":"RBAC in Kubernetes","def":"Controls access to cluster resources via Roles/ClusterRoles (permissions) and RoleBindings/ClusterRoleBindings (assignment to subjects).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c017","term":"NetworkPolicy","def":"Specifies how Pods are allowed to communicate. Default is all-allow; NetworkPolicies whitelist ingress and egress traffic by Pod label, namespace, or CIDR.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c018","term":"Helm","def":"Package manager for Kubernetes. Charts are templated manifests. Enables versioned, repeatable deployments with configurable values.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c019","term":"Resource Requests and Limits","def":"Requests guarantee minimum CPU/memory for scheduling. Limits cap maximum usage. The scheduler uses requests; the runtime enforces limits.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c020","term":"Liveness / Readiness / Startup Probes","def":"Liveness: restart if unhealthy. Readiness: remove from Service endpoints if not ready. Startup: delay other probes until the app initializes.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c021","term":"Horizontal Pod Autoscaler (HPA)","def":"Automatically scales the number of Pod replicas based on CPU/memory utilization or custom metrics.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c022","term":"Terraform","def":"HashiCorp's Infrastructure as Code tool. Declarative HCL configuration, provider-agnostic, manages lifecycle of cloud and on-premises resources.","cat":"Systems","sub":"Terraform"},{"id":"c023","term":"Provider","def":"A plugin that Terraform uses to interact with a specific platform (AWS, Azure, GCP, Kubernetes, etc.). Each provider exposes resources and data sources.","cat":"Systems","sub":"Terraform"},{"id":"c024","term":"Resource","def":"A single infrastructure object Terraform manages (an EC2 instance, a DNS record, a Kubernetes deployment). Defined in HCL with a type and name.","cat":"Systems","sub":"Terraform"},{"id":"c025","term":"Data Source","def":"Reads information from an existing resource not managed by the current configuration. Used to reference infrastructure managed elsewhere.","cat":"Systems","sub":"Terraform"},{"id":"c026","term":"State File","def":"JSON file recording the current state of managed infrastructure. Maps configuration to real-world resources. Must be stored securely and backed up.","cat":"Systems","sub":"Terraform"},{"id":"c027","term":"Remote State Backend","def":"Stores state in a shared location (S3, GCS, Azure Blob, Terraform Cloud) for team collaboration. Supports locking to prevent concurrent modifications.","cat":"Systems","sub":"Terraform"},{"id":"c028","term":"Plan / Apply / Destroy","def":"Plan previews changes. Apply executes them. Destroy removes all managed resources. Plan output should always be reviewed before applying.","cat":"Systems","sub":"Terraform"},{"id":"c029","term":"Modules","def":"Reusable, self-contained packages of Terraform configuration. Accept inputs (variables), produce outputs. Published on the Terraform Registry or stored internally.","cat":"Systems","sub":"Terraform"},{"id":"c030","term":"Variables and Outputs","def":"Variables parameterize configurations (string, number, bool, list, map). Outputs expose values from a module for use elsewhere.","cat":"Systems","sub":"Terraform"},{"id":"c031","term":"terraform init","def":"Initializes a working directory, downloads providers and modules, and configures the backend. Must run before plan or apply.","cat":"Systems","sub":"Terraform"},{"id":"c032","term":"terraform fmt / validate","def":"fmt formats HCL files to canonical style. validate checks syntax and internal consistency without accessing providers.","cat":"Systems","sub":"Terraform"},{"id":"c033","term":"Provisioners","def":"Execute scripts on a resource after creation (local-exec, remote-exec). Considered a last resort — configuration management tools are preferred.","cat":"Systems","sub":"Terraform"},{"id":"c034","term":"Workspaces","def":"Isolated state environments within a single configuration. Useful for separating dev/staging/prod without duplicating code.","cat":"Systems","sub":"Terraform"},{"id":"c035","term":"Terraform Cloud / Enterprise","def":"SaaS/self-hosted platform adding remote execution, state management, policy as code (Sentinel), and team collaboration.","cat":"Systems","sub":"Terraform"},{"id":"c036","term":"Import","def":"Brings existing infrastructure under Terraform management by associating a real resource with a configuration block. State is updated, but code must be written manually.","cat":"Systems","sub":"Terraform"},{"id":"c037","term":"Linux Filesystem Hierarchy","def":"/bin (binaries), /etc (configuration), /home (users), /var (variable data), /tmp (temporary), /proc and /sys (kernel interfaces).","cat":"Systems","sub":"LFCE"},{"id":"c038","term":"systemd","def":"Init system and service manager for modern Linux. Units define services, timers, mounts, and targets. systemctl is the control command.","cat":"Systems","sub":"LFCE"},{"id":"c039","term":"journalctl","def":"Queries the systemd journal for logs. Supports filtering by unit, priority, time range, and boot session.","cat":"Systems","sub":"LFCE"},{"id":"c040","term":"Package Management","def":"apt/dpkg for Debian/Ubuntu, dnf/yum/rpm for RHEL/Fedora. Manages software installation, updates, dependencies, and removal.","cat":"Systems","sub":"LFCE"},{"id":"c041","term":"User and Group Management","def":"useradd, usermod, userdel, groupadd. /etc/passwd stores users, /etc/shadow stores hashed passwords, /etc/group stores groups.","cat":"Systems","sub":"LFCE"},{"id":"c042","term":"File Permissions","def":"Read (4), write (2), execute (1) for owner, group, others. chmod sets permissions, chown changes ownership. SUID, SGID, and sticky bit are special permissions.","cat":"Systems","sub":"LFCE"},{"id":"c043","term":"SELinux / AppArmor","def":"Mandatory Access Control frameworks. SELinux uses labels and policies (enforcing/permissive/disabled). AppArmor uses path-based profiles.","cat":"Systems","sub":"LFCE"},{"id":"c044","term":"iptables / nftables","def":"Linux packet filtering frameworks. Define rules for INPUT, OUTPUT, and FORWARD chains. nftables is the modern replacement with unified syntax.","cat":"Systems","sub":"LFCE"},{"id":"c045","term":"LVM (Logical Volume Manager)","def":"Abstraction layer over physical disks. Physical Volumes → Volume Groups → Logical Volumes. Enables dynamic resizing and snapshots.","cat":"Systems","sub":"LFCE"},{"id":"c046","term":"SSH Configuration","def":"sshd_config controls server behavior: key-based auth, PermitRootLogin, AllowUsers, port, and protocol settings. Key-based auth is preferred over passwords.","cat":"Systems","sub":"LFCE"},{"id":"c047","term":"cron / at","def":"cron schedules recurring tasks via crontab (minute, hour, day, month, weekday). at schedules one-time future tasks.","cat":"Systems","sub":"LFCE"},{"id":"c048","term":"Networking in Linux","def":"ip command manages interfaces, addresses, and routes. ss replaces netstat for socket statistics. /etc/resolv.conf for DNS. NetworkManager or systemd-networkd for management.","cat":"Systems","sub":"LFCE"},{"id":"c049","term":"Process Management","def":"ps, top, htop show processes. kill sends signals (SIGTERM, SIGKILL). nice/renice set priority. & backgrounds, nohup detaches from terminal.","cat":"Systems","sub":"LFCE"},{"id":"c050","term":"Shell Scripting","def":"Bash scripts automate tasks. Variables, conditionals (if/elif/else), loops (for/while), functions, exit codes, and piping are core constructs.","cat":"Systems","sub":"LFCE"},{"id":"c051","term":"RAID Levels","def":"RAID 0 (striping, no redundancy), RAID 1 (mirroring), RAID 5 (striping with parity, min 3 disks), RAID 6 (double parity), RAID 10 (mirror + stripe).","cat":"Systems","sub":"LFCE"},{"id":"c052","term":"Containers on Linux","def":"Built on namespaces (isolation), cgroups (resource limits), and overlay filesystems. Docker and Podman are common runtimes.","cat":"Systems","sub":"LFCE"},{"id":"c053","term":"Labels, Selectors, and Annotations","def":"Labels are key-value pairs used to identify and group objects; selectors query them, and this is how Services find Pods and Deployments find ReplicaSets. Annotations hold non-identifying metadata for tools and libraries and cannot be selected on.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c054","term":"Taints and Tolerations","def":"A taint on a node repels Pods that do not tolerate it. Effects are NoSchedule (blocks new Pods), PreferNoSchedule (soft), and NoExecute (also evicts running Pods). Tolerations on a Pod permit but do not guarantee placement on tainted nodes.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c055","term":"Affinity and Anti-Affinity","def":"Node affinity attracts Pods to nodes by label, in required or preferred form. Pod affinity co-locates Pods with other Pods; pod anti-affinity separates them. Topology keys define the domain — hostname, zone, region — over which the rule applies.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c056","term":"Init Containers","def":"Containers that run to completion in sequence before app containers start. Used for waiting on dependencies, cloning configuration, or setting permissions. A failing init container restarts the Pod according to its restart policy, and the app never starts.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c057","term":"Sidecar Containers","def":"Additional containers in a Pod that run alongside the main application, sharing its network namespace and volumes. Used for log shipping, proxies, and credential refresh. Modern Kubernetes supports native sidecars as init containers with a restart policy of Always.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c058","term":"Pod Lifecycle Phases","def":"Pending (accepted but not all containers running, often awaiting scheduling or image pull), Running, Succeeded (all containers terminated successfully), Failed (at least one terminated in failure), Unknown (node state unreachable).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c059","term":"CrashLoopBackOff / ImagePullBackOff","def":"CrashLoopBackOff means the container starts then exits repeatedly, with the kubelet backing off between restarts — an application or configuration fault. ImagePullBackOff means the image cannot be retrieved, typically a wrong tag, a private registry without imagePullSecrets, or a network issue.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c060","term":"Restart Policy","def":"Pod-level setting controlling container restarts: Always (default, used by Deployments), OnFailure (used by Jobs), Never. The policy applies to all containers in the Pod and cannot be set per container.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c061","term":"Pod Disruption Budget","def":"Declares the minimum available or maximum unavailable Pods for an application during voluntary disruptions such as node drains. It constrains eviction, not node failure, so it protects against maintenance rather than against crashes.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c062","term":"Cordon, Drain, and Uncordon","def":"Cordon marks a node unschedulable without touching running Pods. Drain cordons and then evicts Pods, respecting Pod Disruption Budgets. Uncordon restores schedulability. Drain is the standard preparation for node maintenance.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c063","term":"StorageClass","def":"Defines a provisioner and parameters used for dynamic volume provisioning. A PVC referencing a StorageClass causes a matching PV to be created automatically. The default StorageClass is used when a PVC names none.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c064","term":"Volume Types and Access Modes","def":"emptyDir lives and dies with the Pod; hostPath mounts a node path and is generally discouraged; projected combines Secrets, ConfigMaps, and tokens into one mount. Access modes: ReadWriteOnce (one node), ReadOnlyMany, ReadWriteMany (many nodes), ReadWriteOncePod (a single Pod).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c065","term":"Reclaim Policy","def":"Determines what happens to a PersistentVolume when its claim is deleted. Delete removes the underlying storage; Retain keeps the volume and its data for manual recovery. Dynamically provisioned volumes default to Delete, which is a common source of accidental data loss.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c066","term":"ServiceAccount","def":"Identity for processes running in Pods when calling the Kubernetes API. Every namespace has a default ServiceAccount with minimal permissions. Tokens are projected into the Pod and bound to its lifetime; RBAC grants determine what the account may do.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c067","term":"Security Context","def":"Pod- or container-level security settings: runAsUser and runAsNonRoot, fsGroup, readOnlyRootFilesystem, allowPrivilegeEscalation, privileged, and Linux capabilities. Container-level settings override Pod-level ones where both are present.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c068","term":"Pod Security Admission","def":"Built-in admission controller enforcing the Pod Security Standards at namespace level via labels. Three profiles — privileged, baseline, restricted — and three modes — enforce, audit, warn. Replaced the removed PodSecurityPolicy.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c069","term":"Admission Controllers","def":"Plugins intercepting API requests after authentication and authorization but before persistence. Mutating controllers modify the object; validating controllers accept or reject it. Mutation runs first. Webhooks allow custom policy without patching the API server.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c070","term":"Custom Resource Definitions and Operators","def":"A CRD extends the API with a new resource type. An operator is a controller watching that resource and reconciling actual state toward the declared spec, encoding operational knowledge for stateful software such as databases.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c071","term":"Rolling Update Strategy","def":"Deployment strategy controlled by maxSurge (extra Pods permitted above desired count) and maxUnavailable (Pods allowed to be down). Both default to 25%. Setting maxUnavailable to 0 guarantees no capacity loss at the cost of temporarily higher resource use.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c072","term":"Rollback and Revision History","def":"Deployments retain prior ReplicaSets as revisions, capped by revisionHistoryLimit. `kubectl rollout undo` reverts to the previous revision, and `--to-revision` targets a specific one. `kubectl rollout status` reports progress and detects a stuck rollout.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c073","term":"Cluster Autoscaler and Vertical Pod Autoscaler","def":"Cluster Autoscaler adds or removes nodes when Pods cannot be scheduled or when nodes are underused. VPA adjusts a Pod's resource requests based on observed usage. HPA changes replica count; the three operate on different axes and VPA and HPA conflict on CPU unless carefully configured.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c074","term":"ResourceQuota and LimitRange","def":"ResourceQuota caps aggregate consumption within a namespace — total CPU, memory, and object counts. LimitRange sets per-object defaults, minimums, and maximums. LimitRange supplies the defaults that let Pods without explicit requests satisfy a quota.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c075","term":"Quality of Service Classes","def":"Guaranteed: every container has requests equal to limits for both CPU and memory. Burstable: at least one request is set but the Guaranteed condition is not met. BestEffort: no requests or limits. The class determines eviction order under node pressure.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c076","term":"Container Network Interface (CNI)","def":"Specification and plugin model providing Pod networking. The plugin assigns Pod IPs and establishes routing so that every Pod can reach every other Pod without NAT. Calico, Cilium, and Flannel are common implementations; NetworkPolicy enforcement depends on plugin support.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c077","term":"CoreDNS and Service Discovery","def":"Cluster DNS resolves Services to their ClusterIP. The fully qualified form is service.namespace.svc.cluster.local. Pods in the same namespace can use the short name; cross-namespace access requires at least service.namespace.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c078","term":"Headless Service","def":"A Service with clusterIP set to None. DNS returns the Pod IPs directly instead of a single virtual IP, giving each Pod a stable resolvable hostname. This is how StatefulSet members address one another.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c079","term":"Static Pods","def":"Pods managed directly by the kubelet from manifest files on the node, typically in /etc/kubernetes/manifests, rather than by the API server. Control plane components are commonly run this way. A mirror Pod appears in the API but deleting it does not remove the static Pod.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c080","term":"Ephemeral Containers and kubectl debug","def":"Temporary containers injected into a running Pod for troubleshooting, added through `kubectl debug`. They have no resource guarantees and cannot be restarted, but they allow inspection of distroless or minimal images that contain no shell.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c081","term":"HCL Expressions","def":"HashiCorp Configuration Language supports references, arithmetic, string templates with `${}`, splat expressions, and for-expressions that transform lists and maps. Expressions are evaluated during plan, which is why values unknown until apply appear as \"(known after apply)\".","cat":"Systems","sub":"Terraform"},{"id":"c082","term":"Locals","def":"Named values computed once within a configuration and referenced as `local.name`. Unlike variables they accept no external input; they exist to avoid repeating a complex expression and to give an intermediate calculation a readable name.","cat":"Systems","sub":"Terraform"},{"id":"c083","term":"count and for_each","def":"Meta-arguments creating multiple instances of a resource. `count` produces a numeric index, so removing a middle element shifts every subsequent address and causes unintended destruction and recreation. `for_each` keys instances by a map key or set value, so addresses remain stable.","cat":"Systems","sub":"Terraform"},{"id":"c084","term":"Dynamic Blocks","def":"Construct generating repeatable nested blocks from a collection, used where a resource accepts many similar sub-blocks such as security group rules. Improves conciseness but reduces readability, so it is best reserved for genuinely variable-length content.","cat":"Systems","sub":"Terraform"},{"id":"c085","term":"Conditional Expressions","def":"Ternary form `condition ? true_value : false_value`. Commonly combined with `count = var.enabled ? 1 : 0` to make a resource optional, which is the standard idiom for feature-flagging infrastructure.","cat":"Systems","sub":"Terraform"},{"id":"c086","term":"Implicit and Explicit Dependencies","def":"Terraform builds a dependency graph automatically from references between resources. `depends_on` declares a dependency that has no reference, such as an IAM policy that must exist before an application starts. Over-using `depends_on` reduces parallelism.","cat":"Systems","sub":"Terraform"},{"id":"c087","term":"Lifecycle Meta-Arguments","def":"`create_before_destroy` builds the replacement before removing the original, avoiding downtime where the provider allows it. `prevent_destroy` causes an error rather than destroying a protected resource. `ignore_changes` tells Terraform not to revert attributes modified outside the configuration.","cat":"Systems","sub":"Terraform"},{"id":"c088","term":"Version Constraints","def":"Operators controlling acceptable provider and module versions. `~> 5.0` permits any 5.x release but not 6.0; `~> 5.1.0` permits 5.1.x only. Unconstrained versions make builds non-reproducible when a provider publishes a breaking release.","cat":"Systems","sub":"Terraform"},{"id":"c089","term":"Dependency Lock File","def":"`.terraform.lock.hcl` records the exact provider versions and their checksums selected during init. It belongs in version control so that every machine and CI run resolves identical providers. `terraform init -upgrade` updates it deliberately.","cat":"Systems","sub":"Terraform"},{"id":"c090","term":"State Manipulation Commands","def":"`terraform state list` enumerates managed resources, `state show` prints one, `state mv` changes a resource's address without destroying it, and `state rm` removes it from state while leaving the real object alone. All modify state directly and warrant a backup first.","cat":"Systems","sub":"Terraform"},{"id":"c091","term":"terraform taint and -replace","def":"Marks a resource for destruction and recreation on the next apply. The `taint` command is superseded by `terraform apply -replace=ADDRESS`, which performs the same operation through the normal plan workflow so the change is visible before it happens.","cat":"Systems","sub":"Terraform"},{"id":"c092","term":"Refresh and -refresh-only","def":"Refresh reconciles state with the real infrastructure. `terraform plan -refresh-only` shows what has changed outside Terraform without proposing configuration changes, which is the safe way to inspect drift before deciding how to resolve it.","cat":"Systems","sub":"Terraform"},{"id":"c093","term":"Sensitive Values","def":"Marking a variable or output `sensitive = true` suppresses it in CLI output and plan display. It is not encryption — the value remains in plaintext in the state file, which is the reason remote state must be encrypted and access-controlled.","cat":"Systems","sub":"Terraform"},{"id":"c094","term":"Remote State Data Source","def":"`terraform_remote_state` reads outputs from another configuration's state file, allowing a networking stack to publish subnet IDs that an application stack consumes. Creates a coupling between stacks, so published outputs should be treated as a stable interface.","cat":"Systems","sub":"Terraform"},{"id":"c095","term":"State Locking","def":"Mechanism preventing concurrent operations from corrupting state. S3 backends historically used a DynamoDB table; Terraform Cloud and most managed backends lock natively. Without locking, two simultaneous applies can produce a state file that no longer matches reality.","cat":"Systems","sub":"Terraform"},{"id":"c096","term":"Module Sources and Versioning","def":"Modules may be sourced from the registry, Git URLs, local paths, or object storage. Registry and Git sources support a `version` or ref pin. Unpinned module sources mean the same configuration can produce different infrastructure on different days.","cat":"Systems","sub":"Terraform"},{"id":"c097","term":"Policy as Code","def":"Sentinel (Terraform Cloud and Enterprise) and Open Policy Agent evaluate a plan against organizational rules before apply — blocking public storage buckets, untagged resources, or oversized instances. Enforcement happens between plan and apply, so violations never reach the provider.","cat":"Systems","sub":"Terraform"},{"id":"c098","term":"systemd Unit Types","def":"`.service` runs a process, `.socket` listens and activates a service on connection, `.timer` schedules activation, `.target` groups units as a synchronization point, `.mount` and `.automount` manage filesystems, `.path` triggers on filesystem events.","cat":"Systems","sub":"LFCE"},{"id":"c099","term":"Service Unit Directives","def":"`ExecStart` defines the command. `Restart` accepts no, on-failure, always, and others. `After` and `Before` set ordering only. `Requires` and `Wants` set dependency, with Requires causing failure to propagate and Wants tolerating it. `WantedBy` in the Install section determines what enabling the unit hooks it into.","cat":"Systems","sub":"LFCE"},{"id":"c100","term":"systemd Timers","def":"Scheduling units with `OnCalendar` for wall-clock schedules and `OnBootSec` or `OnUnitActiveSec` for relative ones. `Persistent=true` runs a missed job after downtime — behavior cron lacks. Timers gain journal logging, dependency ordering, and resource control from systemd.","cat":"Systems","sub":"LFCE"},{"id":"c101","term":"Boot Process and GRUB2","def":"Firmware initializes hardware and loads the bootloader; GRUB2 loads the kernel and initramfs; the kernel mounts the root filesystem and starts systemd as PID 1. GRUB2 configuration is generated from `/etc/default/grub` and `/etc/grub.d/` by `grub2-mkconfig` or `update-grub` — the generated file is not edited directly.","cat":"Systems","sub":"LFCE"},{"id":"c102","term":"initramfs","def":"Temporary root filesystem loaded into memory containing the drivers and modules needed to mount the real root — storage controllers, LVM, RAID, encryption. Rebuilt with `dracut` or `update-initramfs` after changes to storage configuration or kernel modules required at boot.","cat":"Systems","sub":"LFCE"},{"id":"c103","term":"Kernel Modules","def":"`lsmod` lists loaded modules, `modprobe` loads with dependency resolution, `modinfo` shows details, `rmmod` unloads. Persistent loading uses `/etc/modules-load.d/`, and blacklisting uses `/etc/modprobe.d/`. Module parameters can be set in the same files.","cat":"Systems","sub":"LFCE"},{"id":"c104","term":"sysctl","def":"Interface to tunable kernel parameters exposed through `/proc/sys`. `sysctl -w` sets a value for the current boot only; persistence requires a file in `/etc/sysctl.d/` and `sysctl --system` or a reboot. Common tuning covers IP forwarding, connection limits, and virtual memory behavior.","cat":"Systems","sub":"LFCE"},{"id":"c105","term":"/etc/fstab and Mount Options","def":"Table of filesystems mounted at boot: device (by UUID or label rather than device name), mount point, type, options, dump, and pass. Options include noexec, nosuid, nodev for hardening, ro, and noatime. A syntax error here can prevent the system from booting normally.","cat":"Systems","sub":"LFCE"},{"id":"c106","term":"Filesystem Types and Repair","def":"ext4 supports both growing and shrinking. XFS is the RHEL default, performs well at scale, and can grow but never shrink. Btrfs and ZFS add snapshots and checksumming. Repair tools are filesystem-specific: `fsck.ext4`, `xfs_repair`, and both require the filesystem unmounted.","cat":"Systems","sub":"LFCE"},{"id":"c107","term":"Partitioning and Partition Tables","def":"MBR supports four primary partitions and disks up to 2 TB. GPT removes both limits and stores redundant headers. `fdisk`, `gdisk`, and `parted` create partitions; `partprobe` or `partx` makes the kernel re-read the table without a reboot.","cat":"Systems","sub":"LFCE"},{"id":"c108","term":"Swap","def":"Disk space used when physical memory is exhausted, as a partition or file. Created with `mkswap`, activated with `swapon`, made persistent in fstab. The `vm.swappiness` parameter controls how readily the kernel swaps; low values suit latency-sensitive workloads.","cat":"Systems","sub":"LFCE"},{"id":"c109","term":"Disk Quotas","def":"Per-user and per-group limits on blocks and inodes, enabled by mount option and configured with `edquota` and `setquota`. Soft limits may be exceeded during a grace period; hard limits cannot be exceeded at all. `repquota` reports usage.","cat":"Systems","sub":"LFCE"},{"id":"c110","term":"Access Control Lists","def":"Extended permissions beyond owner, group, and other. `setfacl -m u:name:rw file` grants a specific user access without changing ownership; `getfacl` displays them. A `+` in the `ls -l` permission string indicates an ACL is present. Default ACLs on a directory are inherited by new files.","cat":"Systems","sub":"LFCE"},{"id":"c111","term":"umask","def":"Mask subtracted from default creation permissions. Files default to 666 and directories to 777 before masking, so a umask of 027 yields 640 for files and 750 for directories. Set per user in shell profiles or system-wide in login configuration.","cat":"Systems","sub":"LFCE"},{"id":"c112","term":"sudo and sudoers","def":"Grants specified commands to specified users, logging each invocation. `/etc/sudoers` is edited with `visudo`, which validates syntax before saving; drop-in files live in `/etc/sudoers.d/`. NOPASSWD removes the password prompt and should be scoped to specific commands rather than ALL.","cat":"Systems","sub":"LFCE"},{"id":"c113","term":"PAM (Pluggable Authentication Modules)","def":"Framework decoupling authentication from applications. Stacks are defined per service in `/etc/pam.d/` across four types — auth, account, password, session — with control flags required, requisite, sufficient, and optional. `pam_pwquality` enforces complexity; `pam_faillock` locks accounts after failed attempts.","cat":"Systems","sub":"LFCE"},{"id":"c114","term":"firewalld","def":"Zone-based dynamic firewall front-end for nftables. Interfaces are assigned to zones with different trust levels. Runtime changes are lost on reload; `--permanent` writes them to configuration and `--reload` activates them. Rich rules cover cases the simple service and port syntax cannot express.","cat":"Systems","sub":"LFCE"},{"id":"c115","term":"DNS Resolution on Linux","def":"`/etc/nsswitch.conf` determines resolution order, and `/etc/hosts` is normally consulted first. On systemd-resolved systems `/etc/resolv.conf` is typically a symlink to a generated stub file, so editing it directly is overwritten. `resolvectl status` shows the effective configuration.","cat":"Systems","sub":"LFCE"},{"id":"c116","term":"Time Synchronization","def":"Accurate time is required for TLS validation, Kerberos, and log correlation. `chronyd` is the common daemon, configured in `chrony.conf` and inspected with `chronyc sources` and `chronyc tracking`. `timedatectl` sets the timezone and reports synchronization state.","cat":"Systems","sub":"LFCE"},{"id":"c117","term":"logrotate","def":"Rotates, compresses, and prunes log files on a schedule defined in `/etc/logrotate.conf` and `/etc/logrotate.d/`. Directives include daily, rotate N, compress, delaycompress, missingok, notifempty, and postrotate scripts for signaling a service to reopen its files.","cat":"Systems","sub":"LFCE"},{"id":"c118","term":"Performance Analysis Tools","def":"`vmstat` shows memory, swap, and CPU state; `iostat` reports per-device I/O and await; `sar` provides historical data from collected samples; `top` and `htop` give live process views. High I/O wait in CPU statistics points at storage rather than at compute.","cat":"Systems","sub":"LFCE"},{"id":"c119","term":"Network Bonding and VLAN Interfaces","def":"Bonding aggregates NICs for redundancy or throughput, with modes including active-backup and 802.3ad LACP. VLAN interfaces tag traffic for a specific VLAN ID on a physical link. Both are configured through NetworkManager or systemd-networkd rather than transient `ip` commands.","cat":"Systems","sub":"LFCE"}],"questions":[{"cat":"Systems","sub":"CKA/CKAD","stem":"A Pod that runs on every node in the cluster for log collection is managed by:","choices":["A StatefulSet","A DaemonSet","A Deployment","A CronJob"],"answer":1,"label":"DaemonSet","why":"DaemonSets ensure one Pod per node, making them ideal for node-level agents like log collectors and monitoring daemons.","id":"q001","n":1},{"cat":"Systems","sub":"LFCE","stem":"A Linux administrator needs to ensure a service starts automatically on boot and restarts on failure. The mechanism is:","choices":["A systemd unit file with Restart=always and WantedBy=multi-user.target","A script in /etc/rc.local","A cron job running every minute","An entry in /etc/inittab"],"answer":0,"label":"systemd unit file","why":"systemd manages service lifecycle. Restart=always handles failures, and WantedBy ensures the service starts at the appropriate target.","id":"q017","n":17},{"cat":"Systems","sub":"Terraform","stem":"The terraform state file should be stored:","choices":["In version control alongside the code","In a remote backend with locking and encryption","On the developer's local machine only","It doesn't need to be stored; Terraform recreates it"],"answer":1,"label":"Remote state backend","why":"Remote backends like S3 with DynamoDB locking or Terraform Cloud provide team access, prevent concurrent modifications, and enable encryption.","id":"q011","n":11},{"id":"q025","n":25,"cat":"Systems","stem":"A cluster has three nodes with GPUs that should run only machine learning workloads. Other Pods must not be scheduled there. The correct configuration is:","choices":["A nodeSelector on all non-ML Pods","A taint on the GPU nodes with matching tolerations on ML Pods","A NetworkPolicy isolating the GPU nodes","A ResourceQuota on the GPU namespace"],"answer":1,"label":"Taint the GPU nodes, tolerate on ML Pods","why":"Taints repel workloads by default, which is the correct direction for a dedicated node pool. Requiring every other Pod in the cluster to carry a nodeSelector is unenforceable and fails the moment someone forgets. Note that a toleration permits scheduling but does not attract — pair with node affinity if ML Pods must land there."},{"cat":"Systems","sub":"CKA/CKAD","stem":"An application requires a stable network identity and persistent storage per replica. The correct workload type is:","choices":["Deployment","Job","StatefulSet","DaemonSet"],"answer":2,"label":"StatefulSet","why":"StatefulSets provide stable hostnames, ordered deployment, and persistent storage per Pod — requirements that Deployments don't meet.","id":"q002","n":2},{"cat":"Systems","sub":"LFCE","stem":"The Linux file permission 750 means:","choices":["Owner: rwx, Group: rw-, Others: r--","Owner: rw-, Group: r-x, Others: none","Owner: r-x, Group: rwx, Others: none","Owner: rwx, Group: r-x, Others: none"],"answer":3,"label":"Permission 750","why":"7=rwx for owner, 5=r-x for group, 0=no access for others.","id":"q018","n":18},{"cat":"Systems","sub":"Terraform","stem":"After modifying a Terraform configuration, the command to preview changes before applying them is:","choices":["terraform init","terraform refresh","terraform plan","terraform validate"],"answer":2,"label":"terraform plan","why":"Plan generates an execution plan showing what will be created, modified, or destroyed without making changes.","id":"q012","n":12},{"id":"q026","n":26,"cat":"Systems","stem":"A Deployment's three replicas all land on the same node, creating a single point of failure. The correct fix is:","choices":["Pod anti-affinity with a topology key of kubernetes.io/hostname","Increasing the replica count to five","A Pod Disruption Budget with minAvailable of 3","Node affinity preferring three different nodes"],"answer":0,"label":"Pod anti-affinity keyed on hostname","why":"Anti-affinity with a hostname topology key instructs the scheduler to place matching Pods on distinct nodes. A PDB constrains voluntary eviction, not initial placement, and more replicas on one node solves nothing."},{"cat":"Systems","sub":"CKA/CKAD","stem":"A Kubernetes Service of type ClusterIP is accessible:","choices":["From any IP on the internet","Only from within the cluster","From outside the cluster via a load balancer","Only from the node running the Pod"],"answer":1,"label":"ClusterIP scope","why":"ClusterIP is the default Service type and provides an internal-only cluster IP address. NodePort or LoadBalancer expose externally.","id":"q003","n":3},{"cat":"Systems","sub":"LFCE","stem":"To view logs from a specific systemd service, the command is:","choices":["tail -f /var/log/messages","journalctl -u service-name","cat /var/log/syslog","dmesg --follow"],"answer":1,"label":"journalctl -u","why":"journalctl -u filters the systemd journal to show only entries for the specified unit, with structured metadata.","id":"q019","n":19}],"meta":{"total":90,"free":10,"split":true}};
